package com.example.demo.controller;
import com.example.demo.domain.usuario.Usuario; import com.example.demo.repository.usuario.UsuarioRepository; import org.junit.jupiter.api.BeforeEach; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.springframework.test.web.servlet.MockMvc; import org.testcontainers.postgresql.PostgreSQLContainer; import org.testcontainers.junit.jupiter.Container; import org.testcontainers.junit.jupiter.Testcontainers;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @Testcontainers class ListaControllerIT {
 @Container static final PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17-alpine");
 @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);}
 @Autowired MockMvc mvc; @Autowired JdbcTemplate jdbc; @Autowired UsuarioRepository usuarios;
 @BeforeEach void clean(){jdbc.execute("TRUNCATE TABLE favoritos, listas, usuarios RESTART IDENTITY CASCADE");}
 private String register(String email)throws Exception {return mvc.perform(post("/api/auth/registro").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"password-123\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();}
 private String field(String json,String name){var m=java.util.regex.Pattern.compile("\\\""+name+"\\\":(?:\\\"([^\\\"]+)\\\"|(\\d+))").matcher(json);if(!m.find())throw new IllegalArgumentException("Campo ausente: "+name);return m.group(1)!=null?m.group(1):m.group(2);}
 @Test void registrarYAutenticar_emailDuplicadoYCredencialesInvalidas_erroresEsperados()throws Exception {register("a@example.com");mvc.perform(post("/api/auth/registro").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"a@example.com\",\"password\":\"password-123\"}")).andExpect(status().isConflict());mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"a@example.com\",\"password\":\"mala-password\"}")).andExpect(status().isUnauthorized());mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"a@example.com\",\"password\":\"password-123\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.token").isNotEmpty());}
 @Test void accederLista_propiaAjenaYSinToken_200403401()throws Exception {String a=register("a@example.com");String b=register("b@example.com");String ta=field(a,"token");String tb=field(b,"token");String list=mvc.perform(post("/api/listas").header("Authorization","Bearer "+ta).contentType(MediaType.APPLICATION_JSON).content("{\"nombre\":\"Propia\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();long id=Long.parseLong(field(list,"id"));mvc.perform(get("/api/listas/"+id).header("Authorization","Bearer "+ta)).andExpect(status().isOk());mvc.perform(get("/api/listas/"+id).header("Authorization","Bearer "+tb)).andExpect(status().isForbidden());mvc.perform(get("/api/listas/"+id)).andExpect(status().isUnauthorized());String favorite=mvc.perform(post("/api/favoritos").header("Authorization","Bearer "+ta).contentType(MediaType.APPLICATION_JSON).content("{\"productoId\":5,\"listaId\":"+id+",\"nota\":\"guardado\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();long favoriteId=Long.parseLong(field(favorite,"id"));mvc.perform(get("/api/favoritos/"+favoriteId).header("Authorization","Bearer "+ta)).andExpect(status().isOk());mvc.perform(get("/api/favoritos/"+favoriteId).header("Authorization","Bearer "+tb)).andExpect(status().isForbidden());mvc.perform(get("/api/favoritos/"+favoriteId)).andExpect(status().isUnauthorized());}
 @Test void accederListaComoAdmin_listaAjena_200()throws Exception {String user=register("user@example.com");String token=field(user,"token");var admin=usuarios.save(new Usuario(null,"admin@example.com",new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder().encode("password-123"),Usuario.Rol.ADMIN));String adminToken=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"admin@example.com\",\"password\":\"password-123\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String t=field(adminToken,"token");String list=mvc.perform(post("/api/listas").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"nombre\":\"Privada\"}")).andReturn().getResponse().getContentAsString();long id=Long.parseLong(field(list,"id"));mvc.perform(get("/api/listas/"+id).header("Authorization","Bearer "+t)).andExpect(status().isOk());}
 @Test void migrarV4ConDatosExistentes_aV6_preservaDatosYAsignaOwnerTecnico()throws Exception {String schema="migracion_tp2";org.flywaydb.core.Flyway.configure().dataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword()).schemas(schema).defaultSchema(schema).target(org.flywaydb.core.api.MigrationVersion.fromVersion("4")).load().migrate();try(var c=java.sql.DriverManager.getConnection(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword());var st=c.createStatement()){st.executeUpdate("INSERT INTO "+schema+".listas(nombre) VALUES ('Lista existente')");var rs=st.executeQuery("SELECT id FROM "+schema+".listas WHERE nombre='Lista existente'");rs.next();long id=rs.getLong(1);st.executeUpdate("INSERT INTO "+schema+".favoritos(producto_id,nota,lista_id) VALUES (77,'favorito legado',"+id+")");}org.flywaydb.core.Flyway.configure().dataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword()).schemas(schema).defaultSchema(schema).load().migrate();try(var c=java.sql.DriverManager.getConnection(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword());var st=c.createStatement()){var rs=st.executeQuery("SELECT l.nombre,u.email,f.producto_id FROM "+schema+".listas l JOIN "+schema+".usuarios u ON u.id=l.usuario_id JOIN "+schema+".favoritos f ON f.lista_id=l.id WHERE l.nombre='Lista existente'");org.junit.jupiter.api.Assertions.assertTrue(rs.next());org.junit.jupiter.api.Assertions.assertEquals("legacy-migration@invalid.local",rs.getString("email"));org.junit.jupiter.api.Assertions.assertEquals(77,rs.getLong("producto_id"));}}}
